                    productId: this.productId,
                    status: "Aguardando..."
                },
                { upsert: true, new: true }
            );

            // Define o timer de inatividade
            this.setInactivityTimer(() => {
                this.handleInactivity();
            }, this.inactivityDelay); // 60 segundos

            await this.interaction.editReply(this.createCartSuccessEmbed(this.channel.url));

            const initialEmbed = this.createPlanSelectionEmbed();
            this.message = await this.channel.send(initialEmbed);
            await this.handlePlanSelection(this.interaction, "30DiasCart");
        } catch (error) {
            console.error("Erro ao criar carrinho:", error);
        }
    };

    /**
     * Executa o método de criar carrinho
     */
    run = async (start) => {
        await this.createCart();

        // Listener para interações dentro do carrinho
        const collector = this.channel.createMessageComponentCollector({ componentType: ComponentType.Button, time: 600000 }); // 10 minutos

        collector.on("collect", async (btnInteraction) => {
            this.interaction = btnInteraction

            if (btnInteraction.user.id !== this.user.id) {
                await btnInteraction.deferUpdate();
                return;
            }

            clearTimeout(this.inactivityTimer);

            // Reinicia o timer de inatividade
            this.setInactivityTimer(() => {
                this.handleInactivity();
            }, this.inactivityDelay);

            switch (btnInteraction.customId) {
                case "7DiasCart":
                case "15DiasCart":
                case "30DiasCart":
                    await btnInteraction.deferUpdate()
                    await this.handlePlanSelection(btnInteraction);
                    break;

                case "cancelOrder":
                    await this.handleCancellation(btnInteraction);
                    break;

                case "addToCart":
                    await this.updateCartQuantity(btnInteraction, "add");
                    break;

                case "removeFromCart":
                    await this.updateCartQuantity(btnInteraction, "remove");
                    break;

                case "finalizePurchase":
                    await this.finalizePurchase(btnInteraction);
                    break;

                case "pixCopyPaste":
                case "qrCode":
                    // Envie o QR Code ou o código de copiar e colar
                    try {
                        const payment = await Cart.findOne({ channelId: this.channel.id });
                        if (payment && payment.paymentId) {
                            const paymentDetails = await this.paymentProcessor.getPayment(payment.paymentId);
                            if (btnInteraction.customId === "qrCode" && paymentDetails.attachment) {
                                await btnInteraction.reply({ files: [paymentDetails.attachment], ephemeral: true });
                            } else if (btnInteraction.customId === "pixCopyPaste" && paymentDetails.pixCopyPasteCode) {
                                await btnInteraction.reply({ content: paymentDetails.pixCopyPasteCode, ephemeral: true });
                            }
                        } else {
                            await btnInteraction.reply({ content: "Pagamento não encontrado.", ephemeral: true });
                        }
                    } catch (error) {
                        console.error("Erro ao enviar detalhes do pagamento:", error);
                        await btnInteraction.reply({ content: "Ocorreu um erro ao obter os detalhes do pagamento.", ephemeral: true });
                    }
                    break;

                case "cancelPayment":
                    await this.handleCancelPayment(btnInteraction);
                    break;

                default:
                    break;
            }
        });

        collector.on("end", () => {
            if (this.inactivityTimer) clearTimeout(this.inactivityTimer);
        });
    };

    /**
     * Helper para capitalizar strings
     * @param {String} str 
     * @returns {String}
     */
    capitalize = (str) => {
        if (typeof str !== 'string') return '';
        return str.charAt(0).toUpperCase() + str.slice(1);
    };
}

module.exports = CartClass;

