                .setFooter({ text: this.interaction.guild.name, iconURL: this.interaction.guild.iconURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 | Usuário:', value: `${this.user.username} - \`${this.user.id}\`` },
                    { name: '📝 | Encerrou um Carrinho:', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '🕒 | Data / Horário do Fechamento:', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)` },
                    { name: '❔ | Motivo:', value: `Cancelado pelo usuário.` }
                );

            await this.sendLog(logEmbed);
            if (this.channel) {
                await Cart.deleteOne({ channelId: this.channel.id });
                await this.channel.delete();
            }
        } catch (error) {
            console.error("Erro ao lidar com cancelamento:", error);
        }
    };

    /**
     * Lida com o cancelamento da ordem via botão de pagamento
     * @param {Discord.Interaction} interaction 
     */
    handleCancelPayment = async (interaction) => {
        try {
            const logEmbed = new EmbedBuilder()
                .setTitle("Sistema de Logs")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild.name, iconURL: this.interaction.guild.iconURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 | Usuário:', value: `${this.user.username} - \`${this.user.id}\`` },
                    { name: '📝 | Encerrou um Carrinho:', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '❔ | Motivo:', value: `Pagamento cancelado pelo usuário.` },
                    { name: '🕒 | Data / Horário do Fechamento:', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)` }
                );

            await this.sendLog(logEmbed);

            // Tente cancelar o pagamento (se aplicável)
            await this.paymentProcessor.cancelPayment(paymentId); // Certifique-se de ter o paymentId armazenado

            if (this.channel) {
                await this.channel.delete();
                await Cart.deleteOne({ channelId: this.channel.id });
            }
        } catch (error) {
            console.error("Erro ao cancelar pagamento:", error);
        }
    };

    /**
     * Cria o carrinho e inicia o processo
     */
    createCart = async () => {
        try {
            const existingCart = await Cart.findOne({ userId: this.user.id });
            if (existingCart) {
                const guildChannel = this.client.channels.cache.get(existingCart.channelId);
                if (guildChannel) {
                    this.channel = guildChannel;
                    this.cartId = existingCart.id;
                    this.quantity = existingCart.quantity;
                    this.selectedPlan = existingCart.selectedPlan;
                    this.days = existingCart.selectedPlan === "mensal" ? 30 : existingCart.selectedPlan === "quizena" ? 15 : 7;
                    return this.interaction ? this.interaction.reply(this.createCartOpenEmbed(guildChannel)) : true
                }
            }

            await this.interaction.reply({ content: "Aguarde um momento, estou criando seu carrinho...", ephemeral: true });

            const thread = await this.interaction.channel.threads.create({
                name: `🛒・${this.user.username}・${this.user.id}`,
                topic: `Carrinho de Compras - ${this.productData.productName} - ${this.cartId}`,
                autoArchiveDuration: 60,
                type: ChannelType.PrivateThread,
                reason: "Criação de carrinho de compras",
                members: [this.user.id],
                permissionOverwrites: [
                    {
                        id: this.user.id,
                        allow: ["ViewChannel"],
                        deny: ["SendMessages"]
                    },
                    {
                        id: this.interaction.guild.id,
                        deny: ["ViewChannel", "SendMessages"]
                    }
                ]
            });

            this.channel = thread;

            // Cria ou atualiza o carrinho no banco de dados
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                {
                    userId: this.user.id,
                    quantity: this.quantity,
                    cartId: this.cartId,
                    productId: this.productId,
                    status: "Aguardando..."
                },
                { upsert: true, new: true }
            );

            // Define o timer de inatividade
            this.setInactivityTimer(() => {
                this.handleInactivity();
            }, this.inactivityDelay); // 60 segundos

            await this.interaction.editReply(this.createCartSuccessEmbed(this.channel.url));

            const initialEmbed = this.createPlanSelectionEmbed();
            this.message = await this.channel.send(initialEmbed);
            await this.handlePlanSelection(this.interaction, "30DiasCart");
        } catch (error) {
            console.error("Erro ao criar carrinho:", error);
        }
    };

    /**
     * Executa o método de criar carrinho
     */
    run = async (start) => {
        await this.createCart();

        // Listener para interações dentro do carrinho
        const collector = this.channel.createMessageComponentCollector({ componentType: ComponentType.Button, time: 600000 }); // 10 minutos

        collector.on("collect", async (btnInteraction) => {
            this.interaction = btnInteraction

            if (btnInteraction.user.id !== this.user.id) {
                await btnInteraction.deferUpdate();
                return;
            }

            clearTimeout(this.inactivityTimer);

            // Reinicia o timer de inatividade
            this.setInactivityTimer(() => {
                this.handleInactivity();
            }, this.inactivityDelay);

            switch (btnInteraction.customId) {
                case "7DiasCart":
                case "15DiasCart":
                case "30DiasCart":
                    await btnInteraction.deferUpdate()
                    await this.handlePlanSelection(btnInteraction);
                    break;

                case "cancelOrder":
                    await this.handleCancellation(btnInteraction);
                    break;

                case "addToCart":
                    await this.updateCartQuantity(btnInteraction, "add");
                    break;

                case "removeFromCart":
                    await this.updateCartQuantity(btnInteraction, "remove");
                    break;

                case "finalizePurchase":
                    await this.finalizePurchase(btnInteraction);
                    break;

                case "pixCopyPaste":
                case "qrCode":
                    // Envie o QR Code ou o código de copiar e colar
                    try {
                        const payment = await Cart.findOne({ channelId: this.channel.id });
                        if (payment && payment.paymentId) {
                            const paymentDetails = await this.paymentProcessor.getPayment(payment.paymentId);
                            if (btnInteraction.customId === "qrCode" && paymentDetails.attachment) {
                                await btnInteraction.reply({ files: [paymentDetails.attachment], ephemeral: true });
                            } else if (btnInteraction.customId === "pixCopyPaste" && paymentDetails.pixCopyPasteCode) {
                                await btnInteraction.reply({ content: paymentDetails.pixCopyPasteCode, ephemeral: true });
                            }
                        } else {
                            await btnInteraction.reply({ content: "Pagamento não encontrado.", ephemeral: true });
                        }
                    } catch (error) {
                        console.error("Erro ao enviar detalhes do pagamento:", error);
                        await btnInteraction.reply({ content: "Ocorreu um erro ao obter os detalhes do pagamento.", ephemeral: true });
                    }
                    break;

                case "cancelPayment":
                    await this.handleCancelPayment(btnInteraction);
                    break;

                default:
                    break;
            }
        });

        collector.on("end", () => {
            if (this.inactivityTimer) clearTimeout(this.inactivityTimer);
        });
    };

    /**
     * Helper para capitalizar strings
     * @param {String} str 
     * @returns {String}
     */
    capitalize = (str) => {
        if (typeof str !== 'string') return '';
        return str.charAt(0).toUpperCase() + str.slice(1);
    };
}

module.exports = CartClass;

