class Ball {
  late Object ball;
  double radius = 6.5;
  double velocityX = 0;
  double velocityY = 0;
  double CUSHION_RESTITUTION = 0.8;
  bool apply = false;

  Ball(String fileName, double initialX, double initialY) {
    ball = Object(
      fileName: fileName,
    );

