Ok, você quer reescrever seu código zlib para usar zstd para compressão e descompressão. O código fornecido lida com a descompressão zlib, e você quer implementar a compressão e descompressão zstd. 

Aqui está uma abordagem estruturada para alcançar isso, juntamente com um exemplo de implementação. Note que você precisará incluir as bibliotecas zstd (provavelmente através de um gerenciador de pacotes em sua linguagem de programação, como 'zstd' em Python ou bibliotecas similares em C++).

**Compreendendo os Passos**

1. **Incluir Zstd Headers:** Certifique-se de incluir os cabeçalhos zstd necessários para as funções de compressão e descompressão.
2. **Inicializar o Zstd Stream:**  Crie um objeto de stream zstd para lidar com a compressão/descompressão.
3. **Compressão:** Use a função de compressão zstd para comprimir os dados de entrada e armazenar o resultado no buffer de destino.
4. **Descompressão:** Use a função de descompressão zstd para descompactar os dados comprimidos de volta para o buffer original.
5. **Error Handling:** Implementar verificações de erro adequadas após cada operação zstd.

**Exemplo de Código (C++)**

Este exemplo assume que você está usando C++ com as bibliotecas zstd. Adaptar conforme necessário para sua linguagem de programação específica.

```cpp
#include <iostream>
#include "zstd.h" // Inclua o cabeçalho zstd

class ZstdHelper
{
public:
    // Função de compressão zstd
    int compress(const uint8_t* source, uint32_t sourceLen, uint8_t** destBuffer, uint32_t* destLen)
    {
        if (sourceLen == 0)
        {
            return -1;
        }

        zstd_stream strm;
        strm.mode = ZSTD_MODE_CHROMA_SATURATED; // Ajuste a qualidade conforme necessário
        strm.compressionLevel = 3; // Ajuste o nível de compressão (1-19)
        strm.destBuffer = *destBuffer;
        strm.destLen = *destLen;

        int ret = zstd_compress(&strm, source, sourceLen);

        if (ret != ZSTD_OK)
        {
            return -1;
        }

        *destLen = strm.destLen;
        return 0;
    }

    // Função de descompressão zstd
    int decompress(const uint8_t* source, uint32_t sourceLen, uint8_t** destBuffer, uint32_t* destLen)
    {
        if (sourceLen == 0)
        {
            return -1;
        }

        zstd_stream strm;
        strm.mode = ZSTD_MODE_DECOMPRESS;
        strm.sourceBuffer = source;
        strm.sourceLen = sourceLen;
        strm.destBuffer = *destBuffer;
        strm.destLen = *destLen;

        int ret = zstd_decompress(&strm);

        if (ret != ZSTD_OK)
        {
            return -1;
        }

        *destLen = strm.destLen;
        return 0;
    }
};

// Exemplo de uso (em uma função separada ou main)
int main()
{
    // Dados de amostra
    uint8_t data[] = "Este é um exemplo de dados para compressão e descompressão zstd";
    uint32_t dataLen = sizeof(data) - 1; // Exclui o terminador nulo

    // Alocar memória para o buffer de destino
    uint8_t* compressedData = nullptr;
    uint32_t compressedLen = 0;

    // Compressão
    ZstdHelper helper;
    int compressResult = helper.compress(data, dataLen, &compressedData, &compressedLen);
    if (compressResult == 0)
    {
        std::cout << "Compressão bem-sucedida. Tamanho comprimido: " << compressedLen << std::endl;
    }
    else
    {
        std::cerr << "Compressão falhou." << std::endl;
        return 1;
    }

    // Descompressão
    uint8_t* decompressedData = nullptr;
    uint32_t decompressedLen = 0;
    int decompressResult = helper.decompress(compressedData, compressedLen, &decompressedData, &decompressedLen);
    if (decompressResult == 0)
    {
        std::cout << "Descompressão bem-sucedida. Tamanho descomprimido: " << decompressedLen << std::endl;
    }
    else
    {
        std::cerr << "Descompressão falhou." << std::endl;
        return 1;
    }

    // Lidar a memória alocada (libertar quando terminar)
    delete[] compressedData;
    delete[] decompressedData;

    return 0;
}
