    // Verificar se os dados descompactados correspondem aos dados originais
    if (dataLen != decompressedLen)
    {
        std::cerr << "Erro: Tamanho de dados descompatado incorreto." << std::endl;
        delete[] compressedData;
        delete[] decompressedData;
        return 1;
    }

    for (uint32_t i = 0; i < dataLen; ++i)
    {
        if (data[i] != decompressedData[i])
        {
            std::cerr << "Erro: Dados descompatados incorretos." << std::endl;
            delete[] compressedData;
            delete[] decompressedData;
            return 1;
        }
    }

    std::cout << "Compressão e descompressão bem-sucedidas." << std::endl;

    // Limpar memória
    delete[] compressedData;
    delete[] decompressedData;

    return 0;
}
