```cpp
#include <iostream>
#include "zstd.h" // Inclua o cabeçalho zstd

class ZstdHelper
{
public:
    // Função de compressão zstd
    int compress(const uint8_t* source, uint32_t sourceLen, uint8_t** destBuffer, uint32_t* destLen)
    {
        if (sourceLen == 0)
        {
            return -1;
        }

        zstd_stream strm;
        strm.mode = ZSTD_MODE_CHROMA_SATURATED; // Ajuste a qualidade conforme necessário
        strm.compressionLevel = 3; // Ajuste o nível de compressão (1-19)
        strm.destBuffer = *destBuffer;
        strm.destLen = *destLen;

        int ret = zstd_compress(&strm, source, sourceLen);

        if (ret != ZSTD_OK)
        {
            return -1;
        }

        *destLen = strm.destLen;
        return 0;
    }

    // Função de descompressão zstd
    int decompress(const uint8_t* source, uint32_t sourceLen, uint8_t** destBuffer, uint32_t* destLen)
    {
        if (sourceLen == 0)
        {
            return -1;
        }

        zstd_stream strm;
        strm.mode = ZSTD_MODE_DECOMPRESS;
        strm.sourceBuffer = source;
        strm.sourceLen = sourceLen;
        strm.destBuffer = *destBuffer;
        strm.destLen = *destLen;

        int ret = zstd_decompress(&strm);

        if (ret != ZSTD_OK)
        {
            return -1;
        }

        *destLen = strm.destLen;
        return 0;
    }
};

// Exemplo de uso (em uma função separada ou main)
int main()
{
    // Dados de amostra
    uint8_t data[] = "Este é um exemplo de dados para compressão e descompressão zstd";
    uint32_t dataLen = sizeof(data) - 1; // Exclui o terminador nulo

    // Alocar memória para o buffer de destino
    uint8_t* compressedData = nullptr;
    uint32_t compressedLen = 0;

    // Compressão
    ZstdHelper helper;
    int compressResult = helper.compress(data, dataLen, &compressedData, &compressedLen);
    if (compressResult == 0)
    {
        std::cout << "Compressão bem-sucedida. Tamanho comprimido: " << compressedLen << std::endl;
    }
    else
    {
        std::cerr << "Compressão falhou." << std::endl;
        return 1;
    }

    // Descompressão
    uint8_t* decompressedData = nullptr;
    uint32_t decompressedLen = 0;
    int decompressResult = helper.decompress(compressedData, compressedLen, &decompressedData, &decompressedLen);
    if (decompressResult == 0)
    {
        std::cout << "Descompressão bem-sucedida. Tamanho descomprimido: " << decompressedLen << std::endl;
    }
    else
    {
        std::cerr << "Descompressão falhou." << std::endl;
        return 1;
    }

    // Lidar a memória alocada (libertar quando terminar)
    delete[] compressedData;
    delete[] decompressedData;

    return 0;
}
